#!/usr/bin/env node
/**
 * Build the vendored CodeMirror 5 chunk.
 *
 * The plugin is shipped without node_modules, so the generated
 * ui/client.editor.js is committed. Run this script after changing the
 * CodeMirror version or scripts/editor-runtime.js.
 *
 * Usage: node scripts/build-editor.mjs [--check]
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const cmRoot = dirname(require.resolve('codemirror/package.json'));
const version = require('codemirror/package.json').version;

const JS_FILES = [
  'lib/codemirror.js',
  'mode/stex/stex.js',
  'addon/edit/matchbrackets.js',
  'addon/edit/closebrackets.js',
  'addon/selection/active-line.js',
  'addon/search/searchcursor.js',
  'addon/search/search.js',
  'addon/dialog/dialog.js',
  'addon/comment/comment.js',
];
const CSS_FILES = ['lib/codemirror.css', 'addon/dialog/dialog.css'];

const read = (relative) => readFileSync(join(cmRoot, relative), 'utf8')
  .replace(/^\/\/# sourceMappingURL=.*$/gmu, '');

const wrap = (source) => `(function (module, exports, define) {\n${source}\n})(undefined, undefined, undefined);`;
const js = JS_FILES.map((file) => wrap(read(file))).join('\n;\n');
const css = CSS_FILES.map(read).join('\n');
const runtime = readFileSync(join(root, 'scripts/editor-runtime.js'), 'utf8');
const license = readFileSync(join(cmRoot, 'LICENSE'), 'utf8');

const banner = `/*! CodeMirror ${version} — https://codemirror.net/5/ — MIT.
 * GENERATED by scripts/build-editor.mjs. Edit scripts/editor-runtime.js instead.
 */`;

const cssInjection = `(function () {
  var css = ${JSON.stringify(css)};
  if (document.querySelector('style[data-plugin-css="dsh-overleaf-workshop/codemirror.css"]')) return;
  var style = document.createElement('style');
  style.setAttribute('data-plugin', 'dsh-overleaf-workshop');
  style.setAttribute('data-plugin-css', 'dsh-overleaf-workshop/codemirror.css');
  style.textContent = css;
  document.head.appendChild(style);
})();`;

const registration = `window.__ModuleLoader__.load({
  id: 'dsh-overleaf-workshop',
  chunk: 'client.editor.js',
  factory: function () { return window.__dshOverleafCodeMirror; },
});`;

const output = `${banner}\n${cssInjection}\n${js}\n;\n${runtime}\n;\n${registration}\n`;
const target = join(root, 'ui/client.editor.js');
const licenseTarget = join(root, 'ui/codemirror-LICENSE');

if (output.split('__ModuleLoader__.load').length !== 2) {
  throw new Error('generated chunk must register exactly one module');
}
if (!output.includes("chunk: 'client.editor.js'")) throw new Error('generated chunk has the wrong chunk name');

if (process.argv.includes('--check')) {
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  const currentLicense = existsSync(licenseTarget) ? readFileSync(licenseTarget, 'utf8') : '';
  if (current !== output || currentLicense !== license) {
    console.error('ui/client.editor.js or ui/codemirror-LICENSE is stale; run npm run build:editor');
    process.exit(1);
  }
  console.log(`CodeMirror ${version} chunk is up to date`);
} else {
  writeFileSync(target, output);
  writeFileSync(licenseTarget, license);
  console.log(`wrote ui/client.editor.js (${output.length} bytes, CodeMirror ${version})`);
  console.log('wrote ui/codemirror-LICENSE');
}
